Iată o implementare de bază a unei liste legate simplu în C. Această implementare include funcții pentru inserarea nodurilor la început, sfârșit și poziții specifice, precum și pentru ștergerea nodurilor și parcurgerea listei.

```c
#include <stdio.h
#include <stdlib.h>

// Structura nodului
struct Node {
    int data;
    struct Node* next;
}

// Funcția de a crea un nod nou
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        printf(„Eroare de memorie
”);
        return NULL;
    }
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// Funcția de a insera un nod la începutul listei
void insertAtBeginning(struct Node** head_ref, int value) {
    struct Node* newNode = createNode(value);
    if (*head_ref == NULL) {
        *head_ref = newNode;
    } else {
        newNode->next = *head_ref;
        *head_ref = newNode;
    }
}

// Funcția de a insera un nod la sfârșitul listei
void insertAtEnd(struct Node** head_ref, int value) {
    struct Node* newNode = createNode(value);
    if (*head_ref == NULL) {
        *head_ref = newNode;
    } else {
        struct Node* lastNode = *head_ref;
        while (lastNode->next != NULL) {
            lastNode = lastNode->next;
        }
        lastNode->next = newNode;
    }
}

// Funcția de a insera un nod la o poziție specifică
void insertAtPosition(struct Node** head_ref, int value, int position) {
    struct Node* newNode = createNode(value);
    if (position == 0) {
        insertAtBeginning(head_ref, value);
    } else {
        struct Node* current = *head_ref;
        int currentPosition = 0;
        while (current != NULL && currentPosition < position - 1) {
            current = current->next;
            currentPosition++;
        }
        if (current == NULL || currentPosition != position - 1) {
            printf(„Poziție în afara intervalului
”);
        } else {
            newNode->next = current->next;
            current->next = newNode;
        }
    }
}

// Funcția de a șterge un nod la începutul listei
void deleteAtBeginning(struct Node** head_ref) {
    if (*head_ref == NULL) {
        printf(„Lista este goală
”);
    } else {
        struct Node* temp = *head_ref;
        *head_ref = (*head_ref)->next;
        free(temp);
    }
}

// Funcția de a șterge un nod la sfârșitul listei
void deleteAtEnd(struct Node** head_ref) {
    if (*head_ref == NULL) {
        printf(„Lista este goală
”);
    } else if ((*head_ref)->next == NULL) {
        free(*head_ref);
        *head_ref = NULL;
    } else {
        struct Node* current = *head_ref;
        while (current->next->next != NULL) {
            current = current->next;
        }
        free(current->next);
        current->next = NULL;
    }
}

// Funcția de a șterge un nod la o poziție specifică
void deleteAtPosition(struct Node** head_ref, int position) {
    if (position == 0) {
        deleteAtBeginning(head_ref);
    } else {
        struct Node* current = *head_ref;
        int currentPosition = 0;
        if (current == NULL || currentPosition == position - 1) {
            printf(„Poziție în afara intervalului
”);
        } else {
            while (current->next->next != NULL && currentPosition != position - 1) {
                current = current->next;
                currentPosition++;
            }
            if (current->next == NULL || currentPosition != position - 1) {
                printf(„Poziție în afara intervalului
”);
            } else {
                struct Node* temp = current->next;
                current->next = current->next->next;
                free(temp);
            }
        }
    }
}

// Funcția de a parcurge lista și de a imprima datele nodurilor
void traverse(struct Node* head) {
    while (head != NULL) {
        printf(”%d -> „, head->data);
        head = head->next;
    }
    printf(„NULL
”);
}

int main() {
    struct Node* head = NULL;

    insertAtEnd(&head, 1);
    insertAtEnd(&head, 2);
    insertAtEnd(&head, 3);
    insertAtEnd(&head, 4);
    insertAtEnd(&head, 5);

    printf(„Lista originală: „);
    traverse(head);

    insertAtBeginning(&head, 0);
    printf(„După inserarea la început: „);
    traverse(head);

    insertAtEnd(head, 6);
    printf(„După inserarea la sfârșit: „);
    traverse(head);

    insertAtPosition(&head, 7, 3);
    printf(„După inserarea la poziția 3: „);
    traverse(head);

    deleteAtBeginning(&head);
    printf(„După ștergerea de la început: „);
    traverse(head);

    deleteAtEnd(&head);
    printf(„După ștergerea de la sfârșit: „);
    traverse(head);

    deleteAtPosition(&head, 2);
    printf(„După ștergerea de la poziția 2: „);
    traverse(head);

    return 0;
}
```

Această implementare oferă funcții de bază pentru a manipula o listă legată simplu, inclusiv inserarea nodurilor la început, sfârșit și poziții specifice, ștergerea nodurilor și parcurgerea listei. Puteți modifica și extinde această implementare după cum este necesar pentru a se potrivi cerințelor dumneavoastră.

