```javascript
function isValidTag(tag) {
    // Verifică dacă eticheta este goală
    if (!tag) return false;

    // Verifică dacă eticheta începe cu un '#'
    if (!tag.startsWith('#')) return false;

    // Elimină caracterul '#' de la început
    tag = tag.substring(1);

    // Definește caracterele permise
    const allowedChars = ['P', 'Y', 'L', 'Q', 'G', 'R', 'J', 'C', 'U', 'V', '0', '2', '8', '9'];

    // Verifică dacă toate caracterele din etichetă sunt permise
    for (let i = 0; i < tag.length; i++) {
        if (!allowedChars.includes(tag[i])) {
            return false;
        }
    }

    // Dacă toate verificările trec, eticheta este validă
    return true;
}
```

