def create_fizzbuzz_dict():
    fizzbuzz_dict = {}
    for i in range(1, 101):
        if i % 3 == 0 and i % 5 == 0:
            fizzbuzz_dict[i] = "FizzBuzz"
        elif i % 3 == 0:
            fizzbuzz_dict[i] = "Fizz"
        elif i % 5 == 0:
            fizzbuzz_dict[i] = "Buzz"
