            # Conform convenției, 1-19, 20, 30, 40, 50, 60, 70, 80, 90, 100
            # avem următoarele reprezentări în cuvinte
            # 1: unu, 2: doi, 3: trei, ..., 100: o sută
            # Așadar, folosim un f-string pentru a crea reprezentarea în cuvinte
            # pentru numerele care nu sunt divizibile cu 3 sau 5
            ones = ["", "unu", "doi", "trei", "patru", "cinci", "șase", "șapte", "opt", "nouă"]
            teens = ["zece", "unsprezece", "treisprezece", "patrusprezece", "cincisprezece", "șaisprezece", "șaptesprezece", "optsprezece", "nouăsprezece"]
            tens = ["", "zece", "douăzeci", "treizeci", "patruzeci", "cincizeci", "șaizeci", "șaptezeci", "optzeci", "nouăzeci"]
            if i < 10:
                fizzbuzz_dict[i] = ones[i]
            elif i < 20:
                fizzbuzz_dict[i] = teens[i-11]
            elif i < 100:
