def create_fizzbuzz_dict():
    def number_to_words(n):
        ones = ["", "unu", "doi", "trei", "patru", "cinci", "șase", "șapte", "opt", "nouă"]
        teens = ["zece", "unsprezece", "treisprezece", "patrusprezece", "cincisprezece", "șaisprezece", "șaptesprezece", "optsprezece", "nouăsprezece"]
        tens = ["", "zece", "douăzeci", "treizeci", "patruzeci", "cincizeci", "șaizeci", "șaptezeci", "optzeci", "nouăzeci"]
        if n < 10:
            return ones[n]
        elif n < 20:
            return teens[n-11]
        elif n < 100:
            tens_digit = tens[n // 10]
            ones_digit = ones[n % 10] if n % 10 != 0 else ""
            return f"{tens_digit}{ones_digit}" if tens_digit != "" else tens[n // 10]
        else:
            hundreds_digit = "o sută" if n == 100 else f"{ones[n // 100 - 1]} sute" if n // 100 > 1 else f"{ones[n // 100]}"
            tens_digit = tens[n // 10 % 10]
            ones_digit = ones[n % 10] if n % 10 != 0 else ""
            return f"{hundreds_digit} {tens_digit}{ones_digit}" if tens_digit != "" else hundreds_digit

    fizzbuzz_dict = {}
    for i in range(1, 101):
        if i % 3 == 0 and i % 5 == 0:
            fizzbuzz_dict[i] = "FizzBuzz"
        elif i % 3 == 0:
