            "pattern": "^([\\w\\-\\.]+|\\$\\([\\w\\-\\.]+\\))$"
          }
        }
      }
    },
    "checksToSkip": {
      "description": "The list of validations to skip",
      "type": "array",
      "_uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  }
